    for c in range(C):
        if input_demo[r][c] == 4:
            output_test_hv[r][c] = 4

# For each 4, fill horizontally and vertically within distance 2
for r4, c4 in [(r, c) for r in range(R) for c in range(C) if input_demo[r][c] == 4]:
    # Horizontal
    for dc in [-2, -1, 0, 1, 2]:
        nc = c4 + dc
        if 0 <= nc < C:
            if input_demo[r4][nc] == 1:
                output_test_hv[r4][nc] = 3
    # Vertical
    for dr in [-2, -1, 0, 1, 2]:
        nr = r4 + dr
        if 0 <= nr < R:
